  output tx, core_halt, write_en, flash_write_en;
  output [7:0] command;
  output [31:0] write_data, data_address;
  wire clk, rst_n, rx, flash_write_done;
  wire [31:0] core_data;
  wire tx, core_halt, write_en, flash_write_en;
  wire [7:0] command;
  wire [31:0] write_data, data_address;
